sys_script_email.script:
(function runMailScript( /* GlideRecord */ current, /* TemplatePrinter */ template,
    /* Optional EmailOutbound */
    email, /* Optional GlideRecord */ email_action,
    /* Optional GlideRecord */
    event) {
    var util = new HackathonExternalUserManagmentUtils(current.getValue('portal'));
    var instanceBaseUrl = util.getInstanceBaseUrl(current.getValue('portal'), true);
    instanceBaseUrl = instanceBaseUrl + current.portal.url_suffix;
    var user = new GlideRecord(HackathonExternalRegConstants.HACKATHON_USER_REGISTRATION_REQUEST_TABLE);
    user.addQuery("email", '=', current.getDisplayValue('email'));
    user.addQuery("portal", current.getValue("portal"));
    user.addQuery("state", HackathonExternalRegConstants.REGISTRATION_PENDING);
	user.setLimit(1);
    user.query();
    if (user.next()) {
        var encoded_token = encodeURIComponent(user.token);
        var url = instanceBaseUrl + "?id=hck_registration_validation&guid=" + encoded_token;
        template.print("<a href=" + url + ">click here</a>");
    }
})(current, template, email, email_action, event);
